1	const PROCESSING_FEE = 5;
2	
3	const BASE_PREMIUMS: Record<string, number> = {
4	  sword: 100,
5	  amulet: 60,
6	};
7	
8	const COMPONENT_BASE_PREMIUM = 25;
9	const COMPONENT_BLOCK_SIZE = 3;
10	const COMPONENT_BLOCK_PREMIUM = 60;
11	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
12	
13	const FIRST_INSURANCE_SURCHARGE = 0.1;
14	const CURSE_SURCHARGE = 0.5;
15	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
16	const HIGH_ENCHANTMENT_THRESHOLD = 5;
17	const LOYALTY_DISCOUNT = 0.2;
18	const LOYALTY_YEARS_THRESHOLD = 2;
19	const FOLLOWUP_CONTRACT_DISCOUNT = 0.15;
20	
21	const INSURANCE_VALUES: Record<string, number> = {
22	  sword: 1000,
23	  amulet: 600,
24	  rune: 250,
25	  moonstone: 250,
26	};
27	
28	const DEDUCTIBLE = 100;
29	const CAP_MULTIPLIER = 2;
30	const HIGH_ENCHANTMENT_CLAIM_THRESHOLD = 8;
31	const HALF_REIMBURSEMENT = 0.5;
32	const FULL_REIMBURSEMENT = 1;
33	
34	interface Item {
35	  type: string;
36	  cursed?: boolean;
37	  enchantment?: number;
38	}
39	
40	interface QuoteStep {
41	  op: "quote";
42	  items: Item[];
43	}
44	
45	interface Damage {
46	  itemType: string;
47	  amount: number;
48	}
49	
50	interface ClaimStep {
51	  op: "claim";
52	  policy: number;
53	  incident: { cause: string; damages: Damage[] };
54	}
55	
56	type Step = QuoteStep | ClaimStep;
57	
58	interface Customer {
59	  yearsWithMHPCO: number;
60	}
61	
62	interface Scenario {
63	  customer: Customer;
64	  steps: Step[];
65	}
66	
67	interface QuoteResult {
68	  premium: number;
69	}
70	
71	interface ClaimResult {
72	  payout: number;
73	  remainingCap: number;
74	}
75	
76	type StepResult = QuoteResult | ClaimResult;
77	
78	interface ScenarioResult {
79	  results: StepResult[];
80	}
81	
82	const componentGroupBase = (count: number): number =>
83	  count === COMPONENT_BLOCK_SIZE
84	    ? COMPONENT_BLOCK_PREMIUM
85	    : count * COMPONENT_BASE_PREMIUM;
86	
87	const countByType = (items: Item[]): Map<string, number> => {
88	  const counts = new Map<string, number>();
89	  for (const item of items) {
90	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
91	  }
92	  return counts;
93	};
94	
95	const isComponent = (item: Item): boolean => COMPONENT_TYPES.has(item.type);
96	
97	const isHighEnchantment = (item: Item): boolean =>
98	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
99	
100	interface PricedUnit {
101	  base: number;
102	  surcharges: number[];
103	}
104	
105	// Per-item surcharge rules on a main item, each a fraction of the item base
106	// applied when its condition holds. New surcharges are added as list entries.
107	const mainItemSurchargeRules: { applies: (item: Item) => boolean; rate: number }[] = [
108	  { applies: (item) => item.cursed === true, rate: CURSE_SURCHARGE },
109	  { applies: isHighEnchantment, rate: HIGH_ENCHANTMENT_SURCHARGE },
110	];
111	
112	const mainItemUnit = (item: Item): PricedUnit => {
113	  const base = BASE_PREMIUMS[item.type];
114	  const surcharges = mainItemSurchargeRules
115	    .filter((rule) => rule.applies(item))
116	    .map((rule) => base * rule.rate);
117	  return { base, surcharges };
118	};
119	
120	const componentUnit = (count: number): PricedUnit => ({
121	  base: componentGroupBase(count),
122	  surcharges: [],
123	});
124	
125	const pricedUnits = (items: Item[]): PricedUnit[] => {
126	  const mainUnits = items.filter((item) => !isComponent(item)).map(mainItemUnit);
127	
128	  const components = items.filter(isComponent);
129	  const componentUnits = [...countByType(components).values()].map(componentUnit);
130	
131	  return [...mainUnits, ...componentUnits];
132	};
133	
134	const unitTotal = (unit: PricedUnit): number =>
135	  unit.base +
136	  unit.base * FIRST_INSURANCE_SURCHARGE +
137	  unit.surcharges.reduce((sum, surcharge) => sum + surcharge, 0);
138	
139	// Policy-level discount fractions applied to the policy base (sum of unit bases).
140	// Each entry that applies contributes its fraction; new modifiers (e.g. follow-up
141	// contract discount) can be added here without touching per-item pricing.
142	const policyBaseDiscountFractions = (customer: Customer, isFollowUp: boolean): number[] => {
143	  const fractions: number[] = [];
144	  if (customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD) fractions.push(LOYALTY_DISCOUNT);
145	  if (isFollowUp) fractions.push(FOLLOWUP_CONTRACT_DISCOUNT);
146	  return fractions;
147	};
148	
149	const quotePremium = (items: Item[], customer: Customer, isFollowUp: boolean): number => {
150	  const units = pricedUnits(items);
151	  const itemsTotal = units.reduce((sum, unit) => sum + unitTotal(unit), 0);
152	  const policyBase = units.reduce((sum, unit) => sum + unit.base, 0);
153	  const policyDiscount = policyBaseDiscountFractions(customer, isFollowUp).reduce(
154	    (sum, fraction) => sum + policyBase * fraction,
155	    0,
156	  );
157	  return Math.ceil(itemsTotal - policyDiscount + PROCESSING_FEE);
158	};
159	
160	interface Policy {
161	  items: Item[];
162	  cap: number;
163	}
164	
165	const createPolicy = (items: Item[]): Policy => {
166	  const insuranceSum = items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
167	  return { items, cap: insuranceSum * CAP_MULTIPLIER };
168	};
169	
170	// Fraction of a damage amount the policy reimburses, before the deductible.
171	// Coverage clauses (e.g. dragon-material full reimbursement) will add branches here.
172	const reimbursementRate = (item: Item | undefined): number =>
173	  (item?.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_THRESHOLD
174	    ? HALF_REIMBURSEMENT
175	    : FULL_REIMBURSEMENT;
176	
177	const reimbursedAmount = (item: Item | undefined, amount: number): number =>
178	  amount * reimbursementRate(item);
179	
180	const damagePayout = (policy: Policy, damage: Damage): number => {
181	  const item = policy.items.find((candidate) => candidate.type === damage.itemType);
182	  return reimbursedAmount(item, damage.amount) - DEDUCTIBLE;
183	};
184	
185	const insuredCountByType = (items: Item[]): Map<string, number> => countByType(items);
186	
187	const validateDamageCounts = (policy: Policy, damages: Damage[]): void => {
188	  const insured = insuredCountByType(policy.items);
189	  const damaged = new Map<string, number>();
190	  for (const damage of damages) {
191	    damaged.set(damage.itemType, (damaged.get(damage.itemType) ?? 0) + 1);
192	  }
193	  for (const [itemType, count] of damaged) {
194	    if (count > (insured.get(itemType) ?? 0)) {
195	      throw new Error(`claim damages more ${itemType} than insured`);
196	    }
197	  }
198	};
199	
200	const processClaim = (policy: Policy, damages: Damage[]): ClaimResult => {
201	  validateDamageCounts(policy, damages);
202	  const payout = damages.reduce((sum, damage) => sum + damagePayout(policy, damage), 0);
203	  return { payout, remainingCap: policy.cap - payout };
204	};
205	
206	export const runScenario = (scenario: Scenario): ScenarioResult => {
207	  const policies: Policy[] = [];
208	  let quoteCount = 0;
209	
210	  const handleQuote = (step: QuoteStep): QuoteResult => {
211	    const isFollowUp = quoteCount > 0;
212	    quoteCount += 1;
213	    policies.push(createPolicy(step.items));
214	    return { premium: quotePremium(step.items, scenario.customer, isFollowUp) };
215	  };
216	
217	  const handleClaim = (step: ClaimStep): ClaimResult =>
218	    processClaim(policies[step.policy], step.incident.damages);
219	
220	  const results = scenario.steps.map((step): StepResult =>
221	    step.op === "quote" ? handleQuote(step) : handleClaim(step),
222	  );
223	  return { results };
224	};
